package main

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"path/filepath"

	"github.com/urfave/cli/v3"
)

// Completion scripts are generated by urfave/cli; this file only adds the
// --install option, which writes the script into the directory the shell looks
// for it in, similarly to what mise does (https://mise.jdx.dev/shell-setup.html).
// Installation doesn't edit the startup files of the shell, it only reports
// what still has to be set up there.

const completionUsage = "Output or install shell completion script"

const completionHelp = `Output or install shell completion script

Print the completion script of bash, zsh, or fish to standard output and
source it, or write it into the completion directory of the shell with
--install.

Examples:
  source <(redact completion bash)
  redact completion zsh --install
  redact completion fish --install`

// completionTarget tells where a shell looks for the completion script of an
// application, and what the user still has to do after it is installed.
type completionTarget struct {
	dir      func() (string, error)
	fileName func(app string) string
	hint     func(dir string) string
}

var completionTargets = map[string]completionTarget{
	"bash": {
		dir:      bashCompletionDir,
		fileName: func(app string) string { return app },
		hint: func(_ string) string {
			return "The bash-completion package must be installed and enabled in your shell."
		},
	},
	"zsh": {
		dir:      zshCompletionDir,
		fileName: func(app string) string { return "_" + app },
		hint: func(dir string) string {
			return fmt.Sprintf(
				"Make sure %s is in $fpath; if it is not, add the following to ~/.zshrc before compinit:\n"+
					"\tfpath=(%s $fpath)\n"+
					"\tautoload -Uz compinit && compinit",
				dir,
				dir,
			)
		},
	},
	"fish": {
		dir:      fishCompletionDir,
		fileName: func(app string) string { return app + ".fish" },
	},
}

// configureCompletion customizes the completion command urfave/cli builds for
// the application, making it visible and adding the --install option.
func configureCompletion(cmd *cli.Command) {
	cmd.Hidden = false
	cmd.Usage = completionUsage
	cmd.Description = completionHelp

	for _, shell := range cmd.Commands {
		target, ok := completionTargets[shell.Name]
		if !ok {
			continue
		}

		shell.Flags = append(shell.Flags, &cli.BoolFlag{
			Name:  "install",
			Usage: "Write the script into the completion directory of the shell",
		})

		shell.Action = installCompletion(shell.Name, target, shell.Action)
	}
}

// installCompletion wraps the script generator of urfave/cli, writing its
// output into the completion directory of the shell instead of stdout.
func installCompletion(shell string, target completionTarget, output cli.ActionFunc) cli.ActionFunc {
	return func(ctx context.Context, cmd *cli.Command) error {
		if !cmd.Bool("install") {
			return output(ctx, cmd)
		}

		script, err := captureCompletion(ctx, cmd, output)
		if err != nil {
			return err
		}

		return writeCompletion(cmd.Root(), shell, target, script)
	}
}

// captureCompletion runs the script generator, which writes to the output of
// the root command, and returns what it has written.
func captureCompletion(ctx context.Context, cmd *cli.Command, output cli.ActionFunc) (string, error) {
	root := cmd.Root()
	stdout := root.Writer

	buf := &bytes.Buffer{}
	root.Writer = buf

	defer func() {
		root.Writer = stdout
	}()

	if err := output(ctx, cmd); err != nil {
		return "", err
	}

	return buf.String(), nil
}

func writeCompletion(root *cli.Command, shell string, target completionTarget, script string) error {
	dir, err := target.dir()
	if err != nil {
		return err
	}

	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("creating completion directory: %w", err)
	}

	name := filepath.Join(dir, target.fileName(root.Name))

	if err := os.WriteFile(name, []byte(script), 0o600); err != nil {
		return fmt.Errorf("writing completion script: %w", err)
	}

	fmt.Fprintf(root.Writer, "Installed %s completion in %s\n", shell, name)

	if target.hint != nil {
		fmt.Fprintf(root.Writer, "%s\n", target.hint(dir))
	}

	return nil
}

func bashCompletionDir() (string, error) {
	base, err := xdgDataDir()
	if err != nil {
		return "", err
	}

	return filepath.Join(base, "bash-completion", "completions"), nil
}

func zshCompletionDir() (string, error) {
	base, err := xdgDataDir()
	if err != nil {
		return "", err
	}

	return filepath.Join(base, "zsh", "site-functions"), nil
}

func fishCompletionDir() (string, error) {
	base, err := xdgConfigDir()
	if err != nil {
		return "", err
	}

	return filepath.Join(base, "fish", "completions"), nil
}

func xdgDataDir() (string, error) {
	home, _ := os.UserHomeDir()

	return xdgDir(os.Getenv, home, "XDG_DATA_HOME", ".local", "share")
}

func xdgConfigDir() (string, error) {
	home, _ := os.UserHomeDir()

	return xdgDir(os.Getenv, home, "XDG_CONFIG_HOME", ".config")
}

// xdgDir resolves an XDG base directory
// (https://specifications.freedesktop.org/basedir-spec/latest/): the
// environment variable wins, the default goes under the home directory. It is
// resolved here and not with os.UserConfigDir() and friends, since those pick
// macOS specific folders, while shells use the XDG locations everywhere.
func xdgDir(env func(string) string, home, envVar string, sub ...string) (string, error) {
	if dir := env(envVar); dir != "" {
		if !filepath.IsAbs(dir) {
			return "", fmt.Errorf("%s is not an absolute path: %q", envVar, dir)
		}

		return dir, nil
	}

	if home == "" {
		return "", fmt.Errorf("neither %s nor a home directory is set", envVar)
	}

	return filepath.Join(append([]string{home}, sub...)...), nil
}
